css:
.tactile-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg, 12px);
  padding: 1.75rem;
  max-width: 360px;
  cursor: pointer;
  transition: transform 0.24s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.24s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.24s ease;
  position: relative;
}

.tactile-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 16px 32px -12px rgba(0, 0, 0, 0.16);
  border-color: var(--primary);
}

.tactile-card-icon-wrap {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md, 8px);
  background: var(--canvas);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  margin-bottom: 1.25rem;
}

.tactile-card-title {
  font-size: 1.25rem;
  font-family: var(--font-heading), sans-serif;
  color: var(--text-primary);
  margin: 0 0 0.5rem;
}

.tactile-card-desc {
  font-size: 0.9rem;
  line-height: 1.55;
  color: var(--text-muted);
  margin: 0 0 1.5rem;
}

.tactile-card-action {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--primary);
}
